<?php
declare(strict_types=1);
require_once __DIR__ . '/conn.php';
require_once __DIR__ . '/panel_helper.php';
if(!sdk_feature_installed($conn)){http_response_code(503);exit('FEATURE_MIGRATION_REQUIRED');}
$owner=sdk_feature_require_roles($conn,['owner']);$P=get_panel_settings($conn);
$q=trim((string)($_GET['q']??''));$mode=(string)($_GET['mode']??'');$where=['1=1'];
if($q!==''){$e=$conn->real_escape_string($q);$where[]="(t.username LIKE '%$e%' OR t.first_name LIKE '%$e%' OR CAST(t.chat_id AS CHAR) LIKE '%$e%' OR u.username LIKE '%$e%')";}
if($mode==='linked')$where[]='t.linked_user_id IS NOT NULL';elseif($mode==='guest')$where[]='t.linked_user_id IS NULL';
$rows=$conn->query('SELECT t.*,u.username panel_username,u.role,u.status FROM telegram_users t LEFT JOIN users u ON u.id=t.linked_user_id WHERE '.implode(' AND ',$where).' ORDER BY t.last_seen_at DESC LIMIT 300');
$stats=$conn->query('SELECT COUNT(*) total,SUM(linked_user_id IS NOT NULL) linked,SUM(linked_user_id IS NULL) guest FROM telegram_users')->fetch_assoc();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Telegram Users</title><style><?=panel_css_vars($P)?>*{box-sizing:border-box}body{margin:0;background:#050810;color:#f8fafc;font-family:Inter,system-ui}.wrap{max-width:1300px;margin:auto;padding:30px 18px 90px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.card{padding:18px;border-radius:18px;background:#0b1222;border:1px solid rgba(255,255,255,.1)}.card b{font-size:1.7rem}.muted{color:#94a3b8}form{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}input,select,button{padding:11px;border-radius:11px;border:1px solid rgba(255,255,255,.12);background:#050a13;color:#fff;font:inherit}button{background:linear-gradient(135deg,#c9a84c,#4f8ef7);color:#07111f;font-weight:900}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.86rem}th,td{padding:11px;border-bottom:1px solid rgba(255,255,255,.07);text-align:left}@media(max-width:650px){.cards{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="head"><div><h1>Telegram users</h1><div class="muted">Linked and guest Telegram identities. Dates are rendered in IST.</div></div><div><a href="owner_console.php" style="color:#bfdbfe">Owner Console</a> · <a href="dashboard.php" style="color:#bfdbfe">Dashboard</a></div></div><div class="cards"><div class="card"><b><?=(int)($stats['total']??0)?></b><div class="muted">Total Telegram users</div></div><div class="card"><b><?=(int)($stats['linked']??0)?></b><div class="muted">Linked panel users</div></div><div class="card"><b><?=(int)($stats['guest']??0)?></b><div class="muted">Free / guest users</div></div></div><section class="card"><form method="get"><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search Chat ID / username / name"><select name="mode"><option value="">All</option><option value="linked" <?=$mode==='linked'?'selected':''?>>Linked</option><option value="guest" <?=$mode==='guest'?'selected':''?>>Guest</option></select><button>Filter</button></form><div class="scroll"><table><thead><tr><th>Telegram</th><th>Chat ID</th><th>Panel link</th><th>Seen</th><th>Guest eligibility</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):$next=$r['guest_last_key_at']?gmdate('Y-m-d H:i:s',strtotime((string)$r['guest_last_key_at'].' UTC')+7*86400):null;?><tr><td><b><?=htmlspecialchars(trim($r['first_name'].' '.$r['last_name']))?></b><br><span class="muted">@<?=htmlspecialchars($r['username'])?></span></td><td><code><?=htmlspecialchars((string)$r['chat_id'])?></code></td><td><?=htmlspecialchars((string)($r['panel_username']??'Guest'))?><?php if($r['panel_username']):?><br><span class="muted"><?=htmlspecialchars((string)$r['role'])?> · <?=((int)$r['status']===1?'active':'disabled')?></span><?php endif;?></td><td><?=htmlspecialchars((string)$r['last_seen_at'])?><br><span class="muted">First: <?=htmlspecialchars((string)$r['first_seen_at'])?></span></td><td>Keys: <?=(int)$r['guest_key_count']?><br><span class="muted"><?= $next?'Next: '.htmlspecialchars($next):'Eligible now' ?></span></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
